/// A slow swell of filtered noise.
fn texture_bloom(sr: f32) -> StereoIr {
    let frames = (2.4 * sr) as usize;
    let mut rng = Rng::new(0xB100);
    let mut lp = [0.0f32; 2];
    let (mut left, mut right) = (vec![0.0; frames], vec![0.0; frames]);
    for i in 0..frames {
        let t = i as f32 / frames as f32;
        let env = (std::f32::consts::PI * t.sqrt()).sin().powi(2);
        let cutoff = 0.02 + 0.2 * t;
        for (ch, out) in [&mut left, &mut right].into_iter().enumerate() {
            lp[ch] += (rng.bipolar() - lp[ch]) * cutoff;
            out[i] = lp[ch] * env;
        }
    }
    StereoIr { left, right }
}

/// Many tones sweeping upward at once.
fn texture_swarm(sr: f32) -> StereoIr {
    let frames = (2.0 * sr) as usize;
    let mut rng = Rng::new(0x5A7A);
    let tones: Vec<(f32, f32, f32, f32)> = (0..40)
        .map(|_| {
            let pan = rng.unipolar();
            (
                120.0 + 1200.0 * rng.unipolar(),
                1.2 + rng.unipolar(),
                pan,
                rng.unipolar() * TAU,
            )
        })
        .collect();
    let (mut left, mut right) = (vec![0.0; frames], vec![0.0; frames]);
    for (hz, climb, pan, start) in tones {
        let mut phase = start;
        for i in 0..frames {
            let t = i as f32 / frames as f32;
            phase += TAU * hz * 2f32.powf(climb * t) / sr;
            let v = phase.sin() * (1.0 - t).powi(2) * t.min(0.05) * 20.0;
            left[i] += v * (1.0 - pan);
            right[i] += v * pan;
        }
    }
    StereoIr { left, right }
}

/// Sparse clicks scattered across a couple of seconds.
fn texture_dust(sr: f32) -> StereoIr {
    let frames = (2.2 * sr) as usize;
    let mut rng = Rng::new(0xD057);
    let (mut left, mut right) = (vec![0.0; frames], vec![0.0; frames]);
    for _ in 0..360 {
        let at = (rng.unipolar() * frames as f32) as usize;
        let level = 0.2 + rng.unipolar();
        let channel = if rng.unipolar() < 0.5 {
            &mut left
        } else {
            &mut right
        };
        let decay = 0.993 + rng.unipolar() * 0.005;
        let mut v = level * if rng.unipolar() < 0.5 { 1.0 } else { -1.0 };
        for s in channel[at.min(frames - 1)..(at + 300).min(frames)].iter_mut() {
            *s += v;
            v *= decay;
        }
    }
    StereoIr { left, right }
}

/// The level a response needs to come out about as loud as it went in.
pub fn ir_gain(left: &[f32], right: &[f32]) -> f32 {
    let energy: f32 = left.iter().chain(right).map(|s| s * s).sum();
    1.0 / (0.5 * energy).max(1e-9).sqrt()
}

/// A response in the library.
#[derive(Clone, Debug)]
pub struct IrSource {
    pub left: Vec<f32>,
    pub right: Vec<f32>,
    pub gain: f32,
}

/// Every generated response at one sample rate.
#[derive(Debug)]
pub struct IrLibrary {
    sets: [Vec<IrSource>; USER_CATEGORY],
}

impl IrLibrary {
    fn make(category: usize, index: usize, sample_rate: f64, sr: f32) -> StereoIr {
        match SPECS.get(category) {
            Some(row) => {
                let (kind, decay, damping) = row[index];
                generate_ir(
                    &IrSpec {
                        kind,
                        decay,
                        damping,
                        predelay: 0.0,
                        seed: 1 + (category * 7 + index) as u32,
                    },
                    sample_rate,
                )
            }
            None => match index {
                0 => texture_bloom(sr),
                1 => texture_swarm(sr),
                _ => texture_dust(sr),
            },
        }
    }

    fn generate(sample_rate: f64) -> Self {
        let mut sets: [Vec<IrSource>; USER_CATEGORY] = Default::default();
        let sr = sample_rate as f32;
        for (category, set) in sets.iter_mut().enumerate() {
            for index in 0..PER_CATEGORY {
                let ir = Self::make(category, index, sample_rate, sr);
                set.push(IrSource {
                    gain: ir_gain(&ir.left, &ir.right),
                    left: ir.left,
                    right: ir.right,
                });
            }
        }
        Self { sets }
    }

    /// The response at `index` of `category`, or the first of the last category if out of range.
    pub fn get(&self, category: usize, index: usize) -> &IrSource {
        let set = &self.sets[category.min(USER_CATEGORY - 1)];
        &set[index.min(set.len() - 1)]
    }
}

/// The shared library for `sample_rate`, generated the first time it is asked for. Allocates.
pub fn library(sample_rate: f64) -> Arc<IrLibrary> {
    static LIBRARIES: OnceLock<Mutex<HashMap<u64, Arc<IrLibrary>>>> = OnceLock::new();
    let mut libraries = LIBRARIES
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    libraries
        .entry(sample_rate.to_bits())
        .or_insert_with(|| Arc::new(IrLibrary::generate(sample_rate)))
        .clone()
}
